function copyCmd(e){const o=e.querySelector(".cmd-code").textContent.trim(),t=e.querySelector(".cmd-copy"),c=currentLang==="en"?"Copied!":"\xA1Copiado!",n=currentLang==="en"?"Copy":"Copiar";navigator.clipboard.writeText(o).then(()=>{t.textContent=c,t.classList.add("copied"),setTimeout(()=>{t.textContent=n,t.classList.remove("copied")},1800)})}
